import pandas as pd

def clean(df):
    df = df.copy()
    # Strip whitespace from text fields
    for col in ['Category', 'Region', 'Product']:
        if col in df.columns:
            df[col] = df[col].astype(str).str.strip()
    # Fix Category label variants
    def fix_category(x):
        s = str(x).strip()
        low = s.lower()
        if low == 'electronics' or low == 'electornics':
            return 'Electronics'
        if low == 'accessories' or low == 'accesories':
            return 'Accessories'
        if low == 'furniture':
            return 'Furniture'
        if low == 'office supplies' or low == 'office suplies':
            return 'Office Supplies'
        return s
    df['Category'] = df['Category'].apply(fix_category)
    # Fix Region whitespace/case variants
    def fix_region(x):
        s = str(x).strip()
        mapping = {'north':'North','south':'South','east':'East','west':'West'}
        return mapping.get(s.lower(), s)
    df['Region'] = df['Region'].apply(fix_region)
    # Standardize Date format
    df['Date'] = pd.to_datetime(df['Date'], errors='coerce').dt.strftime('%Y-%m-%d')
    # Enforce Revenue formula
    df['Revenue'] = df['Quantity'] * df['Price']
    return df

def answer(df):
    df = clean(df)
    grouped = df.groupby('Category', dropna=True)['Revenue'].sum()
    result = {str(k): float(v) for k, v in grouped.items() if pd.notnull(k)}
    return result
